import { readFileSync } from 'node:fs';
import { join } from 'node:path';

/**
 * Throwaway TLS material generated by the `rabbitmq-certs` docker compose service
 * (docker/rabbitmq/tls/generate-certs.sh). The broker's TLS listeners are 5671 (AMQP) and 5551 (stream).
 */
const TLS_DIR = process.env.RABBITMQ_TLS_DIR ?? join(process.cwd(), 'docker', 'rabbitmq', 'tls', 'generated');

export const tlsFile = (name: 'ca.pem' | 'other-ca.pem' | 'client.pem' | 'client-key.pem'): string =>
  readFileSync(join(TLS_DIR, name), 'utf-8');

/** RabbitMQ user matching the client certificate's CN, for SASL EXTERNAL. */
export const TLS_CLIENT_USER = 'e2e-tls-client';

export const TLS_PORTS = { amqpPort: 5671, streamPort: 5551 };
